function extract($, ctx) {
  const items = [];
  const seen = new Set();

  // Each menu category lives inside a div with class "user-items-list"
  $('div.user-items-list').each((_, wrapperDiv) => {
    const $wrapper = $(wrapperDiv);
    let section = null;

    // Try to read the section title from the data-current-context attribute
    const ctxAttr = $wrapper.attr('data-current-context');
    if (ctxAttr) {
      try {
        const ctxObj = JSON.parse(ctxAttr);
        if (ctxObj && ctxObj.sectionTitle) {
          section = cleanText(ctxObj.sectionTitle);
        }
      } catch (e) {
        // ignore parsing errors
      }
    }

    // Fallback: look for the preceding .list-section-title strong element
    if (!section) {
      const $titleEl = $wrapper.prev('div.list-section-title').find('strong');
      if ($titleEl.length) {
        section = cleanText($titleEl.text());
      }
    }

    // Find the list of items
    const $ul = $wrapper.find('ul.user-items-list-simple');
    $ul.find('li.list-item').each((_, li) => {
      const $li = $(li);

      // Dish name
      const $titleEl = $li.find('h2.list-item-content__title');
      let name = cleanText($titleEl.text());
      if (!name) return; // skip empty names

      // Description – all paragraphs that do NOT contain the price (<strong>)
      let description = null;
      const $descWrapper = $li.find('.list-item-content__description');
      const descParts = [];
      $descWrapper.find('p').each((_, p) => {
        const $p = $(p);
        if ($p.find('strong').length) {
          // price paragraph – skip
        } else {
          const txt = cleanText($p.text());
          if (txt) descParts.push(txt);
        }
      });
      if (descParts.length) {
        description = descParts.join(' ');
      }

      // Price – first <strong> inside the description wrapper
      let priceText = $descWrapper.find('strong').first().text();
      priceText = cleanText(priceText);
      const price = priceText ? parsePrice(priceText) : null;

      // Dedup (in case the same menu appears twice)
      const key = (section || '') + '|' + name;
      if (!seen.has(key)) {
        seen.add(key);
        items.push({ section, name, description, price });
      }
    });
  });

  return items;
}
```

